[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Leap Studio — Your Reinvention and Experience Partner</title>
<meta name="description" content="A global creative agency that challenges the status quo to create transformative experiences that win hearts and move markets in the eco-digital era.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
<style>
*,*::before,*::after{margin:0;padding:0;box-sizing:border-box}
:root{
  --bg:#0A0A0A;
  --bg-elevated:#141414;
  --bg-card:#1A1A1A;
  --text:#FFFFFF;
  --text-muted:#999999;
  --text-dim:#666666;
  --accent:#3B82F6;
  --accent-hover:#60A5FA;
  --accent-warm:#F59E0B;
  --border:rgba(255,255,255,0.08);
  --border-hover:rgba(255,255,255,0.15);
  --radius:12px;
  --radius-lg:20px;
  --font:'Inter',system-ui,-apple-system,sans-serif;
  --max-w:1320px;
  --transition:250ms cubic-bezier(.16,1,.3,1);
}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{font-family:var(--font);background:var(--bg);color:var(--text);line-height:1.6;overflow-x:hidden;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}
a{color:inherit;text-decoration:none}
button{font-family:inherit;border:none;background:none;cursor:pointer;color:inherit}
img{max-width:100%;height:auto;display:block}
ul{list-style:none}

.container{width:100%;max-width:var(--max-w);margin:0 auto;padding:0 24px}
@media(min-width:768px){.container{padding:0 48px}}
@media(min-width:1280px){.container{padding:0 64px}}

/* NAV */
.nav{position:fixed;top:0;left:0;right:0;z-index:100;background:rgba(10,10,10,0.85);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-bottom:1px solid var(--border);transition:background var(--transition)}
.nav-inner{display:flex;align-items:center;justify-content:space-between;height:72px;max-width:var(--max-w);margin:0 auto;padding:0 24px}
@media(min-width:768px){.nav-inner{padding:0 48px}}
@media(min-width:1280px){.nav-inner{padding:0 64px}}
.nav-logo{font-weight:800;font-size:22px;letter-spacing:-0.5px;white-space:nowrap}
.nav-logo span{color:var(--accent)}
.nav-links{display:none;gap:32px;align-items:center}
@media(min-width:1024px){.nav-links{display:flex}}
.nav-links a{font-size:14px;font-weight:500;color:var(--text-muted);transition:color var(--transition);position:relative}
.nav-links a:hover{color:var(--text)}
.nav-links a::after{content:'';position:absolute;bottom:-4px;left:0;width:0;height:2px;background:var(--accent);transition:width var(--transition)}
.nav-links a:hover::after{width:100%}
.nav-right{display:flex;align-items:center;gap:16px}
.lang-selector{position:relative}
.lang-btn{display:flex;align-items:center;gap:6px;font-size:13px;font-weight:500;color:var(--text-muted);padding:6px 12px;border-radius:6px;transition:all var(--transition)}
.lang-btn:hover{color:var(--text);background:rgba(255,255,255,0.05)}
.lang-btn svg{width:16px;height:16px;transition:transform var(--transition)}
.lang-btn.open svg{transform:rotate(180deg)}
.lang-dropdown{position:absolute;top:calc(100% + 8px);right:0;min-width:160px;background:var(--bg-elevated);border:1px solid var(--border);border-radius:var(--radius);padding:4px;opacity:0;visibility:hidden;transform:translateY(-8px);transition:all var(--transition);box-shadow:0 16px 48px rgba(0,0,0,0.4)}
.lang-dropdown.open{opacity:1;visibility:visible;transform:translateY(0)}
.lang-dropdown button{display:block;width:100%;text-align:left;padding:10px 14px;font-size:13px;font-weight:500;color:var(--text-muted);border-radius:8px;transition:all var(--transition)}
.lang-dropdown button:hover,.lang-dropdown button.active{color:var(--text);background:rgba(255,255,255,0.06)}
.lang-dropdown button.active{color:var(--accent)}
.contact-btn{display:none;padding:8px 20px;font-size:13px;font-weight:600;background:var(--accent);color:#fff;border-radius:8px;transition:all var(--transition)}
.contact-btn:hover{background:var(--accent-hover);transform:translateY(-1px)}
@media(min-width:1024px){.contact-btn{display:block}}
.hamburger{display:flex;flex-direction:column;gap:5px;padding:8px;cursor:pointer}
@media(min-width:1024px){.hamburger{display:none}}
.hamburger span{width:22px;height:2px;background:var(--text);transition:all var(--transition);border-radius:1px}
.hamburger.open span:nth-child(1){transform:rotate(45deg) translate(5px,5px)}
.hamburger.open span:nth-child(2){opacity:0}
.hamburger.open span:nth-child(3){transform:rotate(-45deg) translate(5px,-5px)}

/* MOBILE MENU */
.mobile-menu{position:fixed;top:72px;left:0;right:0;bottom:0;background:rgba(10,10,10,0.98);backdrop-filter:blur(20px);z-index:99;display:flex;flex-direction:column;padding:32px 24px;opacity:0;visibility:hidden;transform:translateY(-16px);transition:all 350ms cubic-bezier(.16,1,.3,1)}
.mobile-menu.open{opacity:1;visibility:visible;transform:translateY(0)}
.mobile-menu a{font-size:28px;font-weight:700;color:var(--text-muted);padding:16px 0;border-bottom:1px solid var(--border);transition:color var(--transition)}
.mobile-menu a:hover{color:var(--text)}
.mobile-menu .mobile-contact{margin-top:auto;display:block;text-align:center;padding:16px;background:var(--accent);color:#fff;font-weight:600;font-size:16px;border-radius:var(--radius)}

/* HERO */
.hero{position:relative;min-height:100vh;display:flex;align-items:center;padding-top:72px;overflow:hidden}
.hero-bg{position:absolute;inset:0;z-index:0}
.hero-bg::after{content:'';position:absolute;inset:0;background:linear-gradient(135deg,rgba(10,10,10,0.95) 0%,rgba(10,10,10,0.7) 50%,rgba(59,130,246,0.1) 100%)}
.hero .container{position:relative;z-index:1;width:100%}
.hero-carousel{position:relative;overflow:hidden}
.hero-track{display:flex;transition:transform 600ms cubic-bezier(.16,1,.3,1)}
.hero-slide{min-width:100%;padding:40px 0}
@media(min-width:768px){.hero-slide{padding:80px 0}}
.hero-label{display:inline-flex;align-items:center;gap:8px;padding:8px 16px;background:rgba(59,130,246,0.12);border:1px solid rgba(59,130,246,0.2);border-radius:100px;font-size:12px;font-weight:600;color:var(--accent);text-transform:uppercase;letter-spacing:1px;margin-bottom:24px}
.hero-label span{width:6px;height:6px;border-radius:50%;background:var(--accent);animation:pulse 2s infinite}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:0.4}}
.hero-title{font-size:clamp(36px,7vw,80px);font-weight:800;line-height:1.05;letter-spacing:-2px;margin-bottom:24px;max-width:800px}
.hero-title .highlight{color:var(--accent);display:inline}
.hero-desc{font-size:clamp(16px,2vw,20px);color:var(--text-muted);max-width:560px;line-height:1.7;margin-bottom:40px;font-weight:400}
.hero-cta{display:inline-flex;align-items:center;gap:10px;padding:14px 32px;background:var(--accent);color:#fff;font-weight:600;font-size:15px;border-radius:10px;transition:all var(--transition);position:relative;overflow:hidden}
.hero-cta:hover{background:var(--accent-hover);transform:translateY(-2px);box-shadow:0 8px 32px rgba(59,130,246,0.3)}
.hero-cta svg{width:18px;height:18px;transition:transform var(--transition)}
.hero-cta:hover svg{transform:translateX(3px)}
.hero-nav{display:flex;align-items:center;gap:16px;margin-top:48px}
.hero-dots{display:flex;gap:8px}
.hero-dot{width:32px;height:3px;border-radius:2px;background:rgba(255,255,255,0.2);cursor:pointer;transition:all var(--transition)}
.hero-dot.active{background:var(--accent);width:48px}
.hero-arrows{display:flex;gap:8px;margin-left:auto}
.hero-arrow{width:44px;height:44px;display:flex;align-items:center;justify-content:center;border-radius:50%;border:1px solid var(--border);color:var(--text-muted);transition:all var(--transition)}
.hero-arrow:hover{border-color:var(--accent);color:var(--accent);background:rgba(59,130,246,0.08)}
.hero-arrow svg{width:18px;height:18px}
.hero-visual{position:absolute;right:-10%;top:50%;transform:translateY(-50%);width:45%;height:70%;border-radius:var(--radius-lg);overflow:hidden;display:none}
@media(min-width:1024px){.hero-visual{display:block}}
.hero-visual-inner{width:100%;height:100%;background:linear-gradient(135deg,var(--bg-card) 0%,rgba(59,130,246,0.15) 100%);display:flex;align-items:center;justify-content:center}
.hero-visual-placeholder{width:80%;height:80%;border-radius:var(--radius);background:linear-gradient(135deg,rgba(59,130,246,0.08),rgba(245,158,11,0.08));border:1px solid var(--border)}

/* SECTION HEADERS */
.section-header{margin-bottom:48px}
@media(min-width:768px){.section-header{margin-bottom:64px}}
.section-label{font-size:13px;font-weight:600;color:var(--accent);text-transform:uppercase;letter-spacing:2px;margin-bottom:16px}
.section-title{font-size:clamp(32px,5vw,56px);font-weight:800;line-height:1.1;letter-spacing:-1.5px}
.section-subtitle{font-size:clamp(16px,2vw,18px);color:var(--text-muted);max-width:600px;margin-top:16px;line-height:1.7}

/* TEAM SECTION */
.team{padding:120px 0;background:var(--bg)}
.team-regions{display:flex;gap:8px;margin-bottom:48px;overflow-x:auto;scrollbar-width:none;-ms-overflow-style:none;padding-bottom:4px}
.team-regions::-webkit-scrollbar{display:none}
.region-tab{padding:10px 24px;font-size:14px;font-weight:600;color:var(--text-muted);border-radius:100px;border:1px solid var(--border);white-space:nowrap;transition:all var(--transition)}
.region-tab:hover{color:var(--text);border-color:var(--border-hover)}
.region-tab.active{background:var(--accent);color:#fff;border-color:var(--accent)}
.team-carousel{position:relative;overflow:hidden}
.team-track{display:flex;gap:24px;transition:transform 500ms cubic-bezier(.16,1,.3,1)}
.team-card{min-width:300px;max-width:360px;background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius-lg);overflow:hidden;flex-shrink:0;transition:all var(--transition)}
@media(min-width:768px){.team-card{min-width:360px}}
.team-card:hover{border-color:var(--border-hover);transform:translateY(-4px);box-shadow:0 16px 48px rgba(0,0,0,0.3)}
.team-photo{width:100%;height:280px;background:linear-gradient(135deg,var(--bg-elevated),rgba(59,130,246,0.1));position:relative;overflow:hidden}
.team-photo-placeholder{width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:64px;color:rgba(255,255,255,0.1);font-weight:800}
.team-info{padding:28px}
.team-name{font-size:20px;font-weight:700;margin-bottom:4px}
.team-title{font-size:13px;color:var(--accent);font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px}
.team-office{font-size:13px;color:var(--text-dim);margin-bottom:16px}
.team-quote{font-size:14px;color:var(--text-muted);line-height:1.7;font-style:italic;border-left:2px solid var(--accent);padding-left:16px;margin-bottom:20px}
.team-contact{display:inline-flex;align-items:center;gap:6px;font-size:13px;font-weight:600;color:var(--accent);transition:all var(--transition)}
.team-contact:hover{color:var(--accent-hover)}
.team-contact svg{width:14px;height:14px;transition:transform var(--transition)}
.team-contact:hover svg{transform:translateX(3px)}
.team-nav{display:flex;gap:8px;margin-top:32px}
.team-arrow{width:44px;height:44px;display:flex;align-items:center;justify-content:center;border-radius:50%;border:1px solid var(--border);color:var(--text-muted);transition:all var(--transition)}
.team-arrow:hover{border-color:var(--accent);color:var(--accent)}
.team-arrow svg{width:18px;height:18px}

/* WORK SECTION */
.work{padding:120px 0;background:var(--bg-elevated)}
.work-carousel{overflow:visible;position:relative;margin:0 -24px;padding:0 24px}
@media(min-width:768px){.work-carousel{margin:0 -48px;padding:0 48px}}
.work-track{display:flex;gap:24px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;-ms-overflow-style:none;padding-bottom:16px;cursor:grab}
.work-track:active{cursor:grabbing}
.work-track::-webkit-scrollbar{display:none}
.work-card{min-width:320px;max-width:400px;scroll-snap-align:start;flex-shrink:0;border-radius:var(--radius-lg);overflow:hidden;background:var(--bg-card);border:1px solid var(--border);transition:all var(--transition);position:relative}
@media(min-width:768px){.work-card{min-width:400px;max-width:480px}}
.work-card:hover{border-color:var(--border-hover);transform:translateY(-4px);box-shadow:0 20px 60px rgba(0,0,0,0.3)}
.work-thumb{width:100%;height:240px;position:relative;overflow:hidden}
@media(min-width:768px){.work-thumb{height:280px}}
.work-thumb-inner{width:100%;height:100%;background:linear-gradient(135deg,var(--bg-elevated),rgba(59,130,246,0.08));display:flex;align-items:center;justify-content:center;transition:transform 600ms cubic-bezier(.16,1,.3,1)}
.work-card:hover .work-thumb-inner{transform:scale(1.05)}
.work-thumb-label{position:absolute;top:16px;left:16px;padding:6px 14px;background:rgba(10,10,10,0.8);backdrop-filter:blur(8px);border-radius:100px;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:1px;color:var(--text-muted)}
.work-content{padding:24px}
.work-client{font-size:12px;font-weight:600;color:var(--accent);text-transform:uppercase;letter-spacing:1px;margin-bottom:8px}
.work-project-title{font-size:20px;font-weight:700;line-height:1.3;margin-bottom:12px}
.work-excerpt{font-size:14px;color:var(--text-muted);line-height:1.6;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.work-scroll-hint{display:flex;align-items:center;gap:8px;margin-top:32px;color:var(--text-dim);font-size:13px;font-weight:500}
.work-scroll-hint svg{width:20px;height:20px;animation:scrollHint 2s infinite}
@keyframes scrollHint{0%,100%{transform:translateX(0)}50%{transform:translateX(8px)}}

/* CTA BANNER */
.cta-banner{padding:120px 0;position:relative;overflow:hidden}
.cta-banner::before{content:'';position:absolute;inset:0;background:linear-gradient(135deg,rgba(59,130,246,0.06) 0%,transparent 50%,rgba(245,158,11,0.04) 100%)}
.cta-inner{text-align:center;position:relative;z-index:1}
.cta-inner .section-title{max-width:600px;margin:0 auto 16px}
.cta-inner p{font-size:clamp(16px,2vw,18px);color:var(--text-muted);max-width:640px;margin:0 auto 40px;line-height:1.7}
.cta-btn{display:inline-flex;align-items:center;gap:10px;padding:16px 40px;background:var(--accent);color:#fff;font-weight:700;font-size:16px;border-radius:var(--radius);transition:all var(--transition)}
.cta-btn:hover{background:var(--accent-hover);transform:translateY(-2px);box-shadow:0 12px 40px rgba(59,130,246,0.3)}
.cta-btn svg{width:18px;height:18px;transition:transform var(--transition)}
.cta-btn:hover svg{transform:translateX(3px)}

/* HOW WE WORK */
.how-we-work{padding:120px 0;background:var(--bg-elevated)}
.hww-grid{display:grid;grid-template-columns:1fr;gap:48px;align-items:center}
@media(min-width:768px){.hww-grid{grid-template-columns:1fr 1fr;gap:80px}}
.hww-content .section-title{margin-bottom:24px}
.hww-content p{font-size:17px;color:var(--text-muted);line-height:1.8;margin-bottom:32px}
.hww-link{display:inline-flex;align-items:center;gap:8px;font-weight:600;color:var(--accent);font-size:15px;transition:all var(--transition)}
.hww-link:hover{color:var(--accent-hover)}
.hww-link svg{width:16px;height:16px;transition:transform var(--transition)}
.hww-link:hover svg{transform:translateX(4px)}
.hww-visual{height:400px;border-radius:var(--radius-lg);background:linear-gradient(135deg,var(--bg-card),rgba(59,130,246,0.08));border:1px solid var(--border);display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden}
.hww-visual::after{content:'';position:absolute;width:200px;height:200px;border-radius:50%;background:rgba(59,130,246,0.1);filter:blur(80px);top:20%;right:10%}

/* INSIGHTS */
.insights{padding:120px 0;background:var(--bg)}
.insights-grid{display:grid;grid-template-columns:1fr;gap:20px}
@media(min-width:640px){.insights-grid{grid-template-columns:repeat(2,1fr)}}
@media(min-width:1024px){.insights-grid{grid-template-columns:repeat(4,1fr)}}
.insight-card{background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius-lg);overflow:hidden;transition:all var(--transition);cursor:pointer}
.insight-card:hover{border-color:var(--border-hover);transform:translateY(-4px);box-shadow:0 16px 48px rgba(0,0,0,0.2)}
.insight-thumb{height:180px;background:linear-gradient(135deg,var(--bg-elevated),rgba(59,130,246,0.06));position:relative;overflow:hidden}
.insight-type{position:absolute;top:12px;left:12px;padding:4px 12px;background:rgba(10,10,10,0.8);backdrop-filter:blur(8px);border-radius:100px;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:1px}
.insight-type.podcast{color:var(--accent-warm)}
.insight-type.article{color:var(--accent)}
.insight-type.report{color:#10B981}
.insight-body{padding:20px}
.insight-title{font-size:16px;font-weight:700;line-height:1.4;margin-bottom:16px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.insight-cta{font-size:13px;font-weight:600;color:var(--accent);display:inline-flex;align-items:center;gap:6px;transition:all var(--transition)}
.insight-cta:hover{color:var(--accent-hover)}
.insight-cta svg{width:14px;height:14px;transition:transform var(--transition)}
.insight-card:hover .insight-cta svg{transform:translateX(3px)}

/* PRINCIPLES */
.principles{padding:120px 0;background:var(--bg-elevated)}
.principles-grid{display:grid;grid-template-columns:1fr;gap:24px}
@media(min-width:768px){.principles-grid{grid-template-columns:repeat(2,1fr)}}
@media(min-width:1024px){.principles-grid{grid-template-columns:repeat(4,1fr)}}
.principle-card{padding:32px;background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius-lg);transition:all var(--transition);position:relative;overflow:hidden}
.principle-card:hover{border-color:var(--border-hover);transform:translateY(-4px)}
.principle-card::before{content:'';position:absolute;top:0;left:0;right:0;height:3px;background:var(--accent);transform:scaleX(0);transition:transform var(--transition)}
.principle-card:hover::before{transform:scaleX(1)}
.principle-num{font-size:48px;font-weight:900;color:rgba(59,130,246,0.15);line-height:1;margin-bottom:16px}
.principle-title{font-size:18px;font-weight:700;margin-bottom:12px;line-height:1.3}
.principle-desc{font-size:14px;color:var(--text-muted);line-height:1.7}

/* FOOTER */
.footer{padding:80px 0 0;background:var(--bg);border-top:1px solid var(--border)}
.footer-top{display:grid;grid-template-columns:1fr;gap:48px;padding-bottom:64px}
@media(min-width:768px){.footer-top{grid-template-columns:1fr 1fr}}
@media(min-width:1024px){.footer-top{grid-template-columns:2fr 2fr 1fr}}
.footer-cta h3{font-size:24px;font-weight:700;margin-bottom:12px;line-height:1.3}
.footer-cta p{font-size:15px;color:var(--text-muted);line-height:1.7;margin-bottom:20px;max-width:360px}
.footer-cta-link{display:inline-flex;align-items:center;gap:8px;font-weight:600;color:var(--accent);font-size:15px;transition:all var(--transition)}
.footer-cta-link:hover{color:var(--accent-hover)}
.footer-cta-link svg{width:16px;height:16px;transition:transform var(--transition)}
.footer-cta-link:hover svg{transform:translateX(3px)}
.footer-links h4{font-size:13px;font-weight:600;color:var(--text-dim);text-transform:uppercase;letter-spacing:1.5px;margin-bottom:20px}
.footer-links a{display:block;font-size:15px;color:var(--text-muted);padding:6px 0;transition:color var(--transition)}
.footer-links a:hover{color:var(--text)}
.footer-bottom{border-top:1px solid var(--border);padding:24px 0;display:flex;flex-wrap:wrap;gap:16px;justify-content:space-between;align-items:center}
.footer-legal{font-size:12px;color:var(--text-dim)}
.footer-legal-links{display:flex;flex-wrap:wrap;gap:16px}
.footer-legal-links a{font-size:12px;color:var(--text-dim);transition:color var(--transition)}
.footer-legal-links a:hover{color:var(--text-muted)}

/* COOKIE BANNER */
.cookie-banner{position:fixed;bottom:0;left:0;right:0;z-index:200;background:var(--bg-elevated);border-top:1px solid var(--border);padding:20px 24px;transform:translateY(100%);transition:transform 500ms cubic-bezier(.16,1,.3,1);box-shadow:0 -8px 32px rgba(0,0,0,0.3)}
.cookie-banner.show{transform:translateY(0)}
.cookie-inner{max-width:var(--max-w);margin:0 auto;display:flex;flex-wrap:wrap;align-items:center;gap:16px;justify-content:space-between}
.cookie-text{font-size:14px;color:var(--text-muted);flex:1;min-width:280px;line-height:1.6}
.cookie-text a{color:var(--accent);text-decoration:underline}
.cookie-actions{display:flex;gap:10px;flex-wrap:wrap}
